package Thanh.TaxiDriver.AALauncher

import Thanh.TaxiDriver.AALauncher.signs.RoadGeometryCodec

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

class RoadGeometryCodecTest {
    @Test fun decodesPythonEncoderReferenceVector() {
        // Generated by scripts/build_vietnam_osm_bundle.py encode_geometry:
        // (105.0,21.0) -> (105.000123,21.000456) -> (104.9999,20.9999)
        val blob = byteArrayOf(
            128.toByte(),189.toByte(),131.toByte(),20,
            128.toByte(),177.toByte(),145.toByte(),100,
            144.toByte(),7,246.toByte(),1,
            215.toByte(),8,189.toByte(),3
        )
        val g = requireNotNull(RoadGeometryCodec.decode(blob, 123L, 1, 0))
        assertEquals(123L,g.wayId)
        assertEquals(1,g.level)
        assertEquals(6,g.points.size)
        assertEquals(21.0,g.points[0],0.0000001)
        assertEquals(105.0,g.points[1],0.0000001)
        assertEquals(21.000456,g.points[2],0.0000001)
        assertEquals(105.000123,g.points[3],0.0000001)
        assertEquals(20.9999,g.points[4],0.0000001)
        assertEquals(104.9999,g.points[5],0.0000001)
    }

    @Test fun rejectsTruncatedAndOutOfRangeGeometry() {
        assertNull(RoadGeometryCodec.decode(byteArrayOf(0x80.toByte()),1,0,0))
        // Two points whose decoded latitude immediately exceeds 90 degrees.
        val bad = byteArrayOf(
            128.toByte(),132.toByte(),175.toByte(),86,0,
            0,0
        )
        assertNull(RoadGeometryCodec.decode(bad,1,0,0))
    }
}
